import { test } from 'node:test'
import assert from 'node:assert/strict'
import { createServer } from 'node:http'
import { createApp } from '../src/app.mjs'

const prices = { A: 10, B: 25, C: 33.33, D: 0.1 }
const pricing = { priceOf: async (sku) => prices[sku] }

async function withApp(fn) {
  const server = createServer(createApp({ pricing }))
  await new Promise((r) => server.listen(0, r))
  const base = `http://localhost:${server.address().port}`
  try { return await fn(base) } finally { server.close() }
}

const post = (base, items) =>
  fetch(`${base}/orders`, { method: 'POST', body: JSON.stringify({ items }) }).then((r) => r.json())

const totalFor = (items) => withApp(async (base) => (await post(base, items)).total)

// Characterization tests: pin current behaviour (incl. questionable parts) so a refactor can't change it silently.
test('no discount below threshold', async () => {
  assert.equal(await totalFor([{ sku: 'A', qty: 5 }]), 50)
})
test('multiple lines are summed', async () => {
  assert.equal(await totalFor([{ sku: 'A', qty: 2 }, { sku: 'B', qty: 2 }]), 70)
})
test('exactly 100 gets no discount (threshold is strictly greater)', async () => {
  assert.equal(await totalFor([{ sku: 'A', qty: 10 }]), 100)
})
test('just over 100 gets 10% off', async () => {
  assert.equal(await totalFor([{ sku: 'A', qty: 11 }]), 99) // 110 -> 99
})
test('large order gets 10% off', async () => {
  assert.equal(await totalFor([{ sku: 'B', qty: 40 }]), 900) // 1000 -> 900
})
test('discount applies to whole order, not just the excess', async () => {
  assert.equal(await totalFor([{ sku: 'A', qty: 10 }, { sku: 'D', qty: 10 }]), 90) // 101 -> 90.9 -> 90
})
test('total is floored to whole euros (cents dropped)', async () => {
  assert.equal(await totalFor([{ sku: 'C', qty: 1 }]), 33)
  assert.equal(await totalFor([{ sku: 'C', qty: 4 }]), 133) // 133.32 -> 119.988 -> 119? see below
})
test('GET returns the stored order with same total', async () => {
  await withApp(async (base) => {
    const o = await post(base, [{ sku: 'B', qty: 40 }])
    assert.deepEqual(await fetch(`${base}/orders/${o.id}`).then((r) => r.json()), o)
  })
})
EOF
node --test 2>&1 | grep -E "^# (pass|fail)|expected|actual|not ok"

